import React, { useEffect, useState } from "react";
import type { SupportNote } from "../types";
import {
  createNote,
  listNotesByItinerary,
  updateNote,
} from "../../../sessionServices/support/supportNotesService";
import { writeAuditLog } from "../../../sessionServices/audit/auditLogsService";
import { useAuth } from "../../auth/AuthContext";

interface Props {
  itineraryId: string;
}

type NoteWithId = SupportNote & { id: string };

export function SupportNotePanel({ itineraryId }: Props) {
  const { user } = useAuth();
  const [notes, setNotes] = useState<NoteWithId[]>([]);
  const [loading, setLoading] = useState(true);
  const [newNote, setNewNote] = useState("");
  const [saving, setSaving] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editText, setEditText] = useState("");

  async function load() {
    const data = await listNotesByItinerary(itineraryId);
    setNotes(data);
    setLoading(false);
  }

  useEffect(() => { load(); }, [itineraryId]);

  async function handleAdd() {
    if (!user || !newNote.trim()) return;
    setSaving(true);
    const id = await createNote({ itineraryId, authorId: user.uid, note: newNote.trim() });
    await writeAuditLog({
      entityType: "supportNote",
      entityId: id,
      action: "add_note",
      after: { itineraryId, note: newNote.trim() },
      performedBy: user.uid,
    });
    setNewNote("");
    setSaving(false);
    load();
  }

  async function handleUpdate(id: string) {
    if (!user || !editText.trim()) return;
    await updateNote(id, editText.trim());
    await writeAuditLog({
      entityType: "supportNote",
      entityId: id,
      action: "update",
      after: { note: editText.trim() },
      performedBy: user.uid,
    });
    setEditingId(null);
    load();
  }

  return (
    <div className="space-y-4">
      <h3 className="text-sm font-semibold uppercase tracking-wide text-gray-700">
        Internal notes
      </h3>

      {/* Add note */}
      <div className="flex gap-2">
        <textarea
          rows={2}
          placeholder="Add an internal note…"
          value={newNote}
          onChange={(e) => setNewNote(e.target.value)}
          className="block flex-1 rounded-lg border border-gray-300 px-3 py-2 text-sm text-gray-900 focus:border-gray-800 focus:outline-none focus:ring-1 focus:ring-gray-800"
        />
        <button
          onClick={handleAdd}
          disabled={saving || !newNote.trim()}
          className="self-end rounded-lg bg-gray-900 px-4 py-2 text-sm font-medium text-white disabled:opacity-50"
        >
          {saving ? "…" : "Add"}
        </button>
      </div>

      {loading ? (
        <div className="h-5 w-5 animate-spin rounded-full border-4 border-gray-300 border-t-gray-800" />
      ) : notes.length === 0 ? (
        <p className="text-xs text-gray-400">No notes yet.</p>
      ) : (
        <div className="space-y-2">
          {notes.map((n) => (
            <div key={n.id} className="rounded-lg bg-yellow-50 p-3 ring-1 ring-yellow-100">
              {editingId === n.id ? (
                <div className="space-y-2">
                  <textarea
                    rows={2}
                    value={editText}
                    onChange={(e) => setEditText(e.target.value)}
                    className="block w-full rounded-lg border border-gray-300 px-3 py-1.5 text-sm focus:outline-none"
                  />
                  <div className="flex gap-2">
                    <button
                      onClick={() => handleUpdate(n.id)}
                      className="rounded bg-gray-900 px-3 py-1 text-xs text-white"
                    >Save</button>
                    <button
                      onClick={() => setEditingId(null)}
                      className="rounded border border-gray-300 px-3 py-1 text-xs text-gray-600"
                    >Cancel</button>
                  </div>
                </div>
              ) : (
                <div className="flex items-start justify-between gap-2">
                  <p className="text-sm text-gray-800">{n.note}</p>
                  <button
                    onClick={() => { setEditingId(n.id); setEditText(n.note); }}
                    className="shrink-0 text-xs text-gray-400 underline hover:text-gray-700"
                  >Edit</button>
                </div>
              )}
              <p className="mt-1 text-xs text-gray-400">{formatTs(n.createdAt)}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function formatTs(ts: unknown): string {
  try {
    return (ts as { toDate: () => Date }).toDate().toLocaleString("en-CA");
  } catch {
    return "";
  }
}
